package service;
import datastructures.WaitingListQueue;import exceptions.BookingNotFoundException;import exceptions.InvalidRoomException;import exceptions.RoomNotAvailableException;import model.Booking;import model.Guest;import model.Room;
/** Coordinates reservations, cancellation and waiting-list promotion. */
public class ReservationService{
 private final RoomService roomService;private final BookingService bookingService;private final WaitingListQueue waitingList;
 public ReservationService(RoomService rs,BookingService bs,WaitingListQueue q){if(rs==null||bs==null||q==null)throw new IllegalArgumentException("Dependencies are required.");roomService=rs;bookingService=bs;waitingList=q;}
 public Booking reserve(Guest guest,String type,int nights)throws InvalidRoomException{if(nights<=0)throw new IllegalArgumentException("Planned nights must be at least 1.");String valid=roomService.validateType(type);Booking b=bookingService.createBooking(guest,valid,nights);try{Room r=roomService.allocateRoom(valid);b.assignRoom(r);System.out.println("Room allocated! Booking #"+b.getBookingId()+" -> Room "+r.getNumber()+" ("+valid+").");}catch(RoomNotAvailableException e){waitingList.enqueue(b);System.out.println(e.getMessage()+" Booking #"+b.getBookingId()+" added to waiting list (position "+waitingList.size()+").");}return b;}
 public void promoteFromWaitingList(String type){Booking w=waitingList.removeFirstOfType(type);if(w==null)return;try{Room r=roomService.allocateRoom(type);w.assignRoom(r);System.out.println("Waiting list update: Booking #"+w.getBookingId()+" ("+w.getGuest().getName()+") now allocated Room "+r.getNumber()+".");}catch(RoomNotAvailableException e){waitingList.enqueueFirst(w);}}
 public void cancel(int id)throws BookingNotFoundException{Booking b=bookingService.findById(id);if(b.getStatus()==Booking.Status.WAITING){waitingList.removeByBookingId(id);b.cancel();System.out.println("Waiting-list booking #"+id+" cancelled.");return;}if(b.getStatus()==Booking.Status.ALLOCATED){String type=b.getRoomType();roomService.releaseRoom(b.getRoom());b.cancel();System.out.println("Booking #"+id+" cancelled. Room released.");promoteFromWaitingList(type);return;}throw new IllegalStateException("Only waiting or allocated bookings can be cancelled.");}
}
